        unitIndex: true,
        unitsComplete: ix ? ix.state === "PRESENT" : null,
        indexObserved: ix ? ix.state : null,
        indexReason: ix ? ix.bound || ix.detail || null : null,
        reason: r.condition || r.detail || null
