          doc_sha: d.doc_sha,
          text: d.text,
          sig_armored: d.sig_armored,
          attestor: { member: d.attestor_member, key_b64: d.attestor_key },
          delivered_by: this.#deliveredBy(d),
          gate_version: d.gate_version,
          ratified_at: d.ratified_at
